export type ProtonLoginErrorCode =
    | "INVALID_CREDENTIALS"
    | "TWO_FACTOR_REQUIRED"
    | "TWO_FACTOR_INVALID"
    | "CAPTCHA_REQUIRED"
    | "CAPTCHA_INVALID"
    | "CAPTCHA_CANCELLED"
    | "CANCELLED"
    | "NETWORK_ERROR"
    | "TIMEOUT"
    | "MISSING_EXECUTABLE"
    | "SESSION_PERSISTENCE"
    | "CONFIGURATION_ERROR"
    | "UNKNOWN";

export type ProtonSessionCheckCode = "INVALID_SESSION" | "NETWORK_ERROR" | "TIMEOUT" | "MISSING_EXECUTABLE" | "SESSION_PERSISTENCE" | "UNKNOWN";

export interface ProtonSessionCheckResult {
    valid: boolean;
    username?: string;
    expiresIn?: string;
    code?: ProtonSessionCheckCode;
    error?: string;
}

export interface ProtonLoginResult {
    success: boolean;
    username?: string;
    code?: ProtonLoginErrorCode;
    message?: string;
    error?: string;
    retryable?: boolean;
    captchaUrl?: string;
    /** `false` quando a máquina não guarda a sessão: ela vale só nesta execução. */
    persisted?: boolean;
}

export type ProtonPlanStatus = "free" | "premium" | "unknown";

export interface ProtonPlanResult {
    success: boolean;
    status: ProtonPlanStatus;
    maxTier?: number;
    planName?: string;
    planTitle?: string;
    checkedAt?: string;
    error?: string;
}

export interface ProtonOptimizationProgress {
    phase: "ping" | "preparing" | "testing" | "finalizing" | "completed" | "failed" | "cancelled";
    total: number;
    tested: number;
    succeeded: number;
    server?: string;
    downloadMbps?: number;
    uploadMbps?: number;
    pingMs?: number;
    status?: "testing" | "success" | "failed";
}

export interface ProtonOptimizationResult {
    success: boolean;
    server?: string;
    country?: string;
    city?: string;
    tier?: string;
    load?: number;
    score?: number;
    pingMs?: number;
    downloadMbps?: number;
    uploadMbps?: number;
    speedTested?: number;
    speedSucceeded?: number;
    endpoint?: string;
    confFile?: string;
    error?: string;
}

export interface RunConfgenOptions {
    args: string[];
    exePath?: string;
    stdin?: string;
    timeoutMs?: number;
    signal?: AbortSignal;
    onProgress?: (progress: ProtonOptimizationProgress) => void;
    log?: (level: "info" | "warn" | "error", message: string, data?: Record<string, unknown>) => void;
    runtimeDirectory?: string;
}

export interface ConfgenResult {
    code: number | null;
    stdout: string;
    stderr: string;
    json?: Record<string, unknown>;
}

