const materializedEmbeddedLinuxAssets = new Map<string, string>();

function isUsableEmbeddedLinuxExecutable(filePath: string, sha256: string): boolean {
    try {
        const stat = fs.lstatSync(filePath);
        if (!stat.isFile() || stat.isSymbolicLink() || (stat.mode & 0o022) !== 0) return false;
        fs.accessSync(filePath, fs.constants.X_OK);
        const digest = createHash("sha256").update(fs.readFileSync(filePath)).digest("hex");
        return digest === sha256;
    } catch {
        return false;
    }
}

function ensureEmbeddedLinuxRuntimeDirectory(directory: string): string {
    const resolved = path.resolve(directory);
    let current = resolved;
    const { root } = path.parse(current);
    while (current !== root) {
        try {
            if (fs.lstatSync(current).isSymbolicLink()) throw new Error("diretório de runtime do plugin contém link simbólico");
        } catch (error) {
            if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
        }
        current = path.dirname(current);
    }
    fs.mkdirSync(resolved, { recursive: true, mode: 0o700 });
    const stat = fs.lstatSync(resolved);
    if (!stat.isDirectory() || stat.isSymbolicLink()) throw new Error("diretório de runtime do plugin inválido");
    fs.chmodSync(resolved, 0o700);
    return resolved;
}

export function materializeEmbeddedLinuxAsset(name: EmbeddedLinuxAssetName, directory: string): string {
    if (process.platform !== "linux" || process.arch !== "x64") throw new Error("asset Linux solicitado fora do Linux x64");
    const asset = EMBEDDED_LINUX_ASSETS[name];
    const targetDirectory = ensureEmbeddedLinuxRuntimeDirectory(directory);
    const cacheKey = `${targetDirectory}/${name}`;
    const cached = materializedEmbeddedLinuxAssets.get(cacheKey);
    if (cached && isUsableEmbeddedLinuxExecutable(cached, asset.sha256)) return cached;

    const target = path.join(targetDirectory, `.golive-runtime-${name}-${asset.sha256.slice(0, 16)}`);
    if (isUsableEmbeddedLinuxExecutable(target, asset.sha256)) {
        materializedEmbeddedLinuxAssets.set(cacheKey, target);
        return target;
    }

    const payload = gunzipSync(Buffer.from(asset.gzipBase64, "base64"));
    const digest = createHash("sha256").update(payload).digest("hex");
    if (digest !== asset.sha256) throw new Error(`asset Linux ${name} falhou na verificação de integridade`);

    const staging = path.join(targetDirectory, `.golive-runtime-${name}-${randomUUID()}.tmp`);
    let fd: number | undefined;
    try {
        fd = fs.openSync(staging, "wx", 0o700);
        fs.writeFileSync(fd, payload);
        try { fs.fsyncSync(fd); } catch {}
        fs.closeSync(fd);
        fd = undefined;
        fs.chmodSync(staging, 0o700);
        try {
            fs.renameSync(staging, target);
        } catch (error) {
            if (isUsableEmbeddedLinuxExecutable(target, asset.sha256)) return target;
            throw error;
        }
        if (!isUsableEmbeddedLinuxExecutable(target, asset.sha256)) throw new Error(`asset Linux ${name} não ficou executável`);
        materializedEmbeddedLinuxAssets.set(cacheKey, target);
        return target;
    } finally {
        if (fd !== undefined) {
            try { fs.closeSync(fd); } catch {}
        }
        try { fs.rmSync(staging, { force: true }); } catch {}
    }
}

function logError(error: unknown): string {
    return safeDiagnosticDetail(error, 500);
}

function abortError(): Error {
    const error = new Error("Operação Proton cancelada.");
    error.name = "AbortError";
    return error;
}

const protonLoginQueues = new Map<string, Promise<void>>();
const protonLoginGenerations = new Map<string, number>();
const activeProtonLogins = new Map<string, AbortController>();

function dataDirKey(dataDir: string): string {
    const resolved = path.resolve(dataDir);
    try { return fs.realpathSync(resolved); } catch { return resolved; }
}

function cancelledLoginResult(): ProtonLoginResult {
    return { success: false, code: "CANCELLED", message: LOGIN_CANCELLED_ERROR, error: LOGIN_CANCELLED_ERROR, retryable: true };
}

function usernamesMatch(expected: string, actual: string): boolean {
    return protonUsernamesMatch(expected, actual);
}

async function withProtonLoginLock<T>(dataDir: string, operation: () => Promise<T>): Promise<T> {
    const key = dataDirKey(dataDir);
    const previous = protonLoginQueues.get(key) ?? Promise.resolve();
    let release!: () => void;
    const gate = new Promise<void>(resolve => { release = resolve; });
    const queued = previous.catch(() => undefined).then(() => gate);
    protonLoginQueues.set(key, queued);
    await previous.catch(() => undefined);
    try {
        return await operation();
    } finally {
        release();
        if (protonLoginQueues.get(key) === queued) protonLoginQueues.delete(key);
    }
}

function candidatePaths(): string[] {
    const isWindows = process.platform === "win32";
    const isLinux = process.platform === "linux";
    if (isLinux && process.arch !== "x64") {
        return [];
    }
    if (!isWindows && !isLinux) {
        return [];
    }
    const exeName = isWindows ? "proton-confgen.exe" : "proton-confgen";
    const archSubdir = isWindows ? "win32-x64" : "linux-x64";
    const candidates = [
        process.env.GOLIVE_PLUGIN_PROTON_CONFGEN,
        process.resourcesPath ? path.join(process.resourcesPath, "extra", "proton-confgen", exeName) : undefined,
        path.join(__dirname, "bin", archSubdir, exeName),
        path.join(__dirname, "goLiveBypass", "bin", archSubdir, exeName),
        path.resolve(__dirname, "../../src/userplugins/goLiveBypass/bin", archSubdir, exeName),
        path.resolve(__dirname, "../src/userplugins/goLiveBypass/bin", archSubdir, exeName),
        path.resolve(process.cwd(), "goLiveBypass/bin", archSubdir, exeName),
        path.resolve(process.cwd(), "src/userplugins/goLiveBypass/bin", archSubdir, exeName),
        path.resolve(process.cwd(), "../tools/proton-confgen/build", exeName),
    ].filter((value): value is string => typeof value === "string" && value.length > 0);
    return [...new Set(candidates.map(value => path.resolve(value)))];
}

function isUsableConfgenExecutable(candidate: string): boolean {
    try {
        let current = path.resolve(candidate);
        const { root } = path.parse(current);
        while (current !== root) {
            const info = fs.lstatSync(current);
            if (info.isSymbolicLink()) return false;
            current = path.dirname(current);
        }
        const stat = fs.lstatSync(candidate);
        if (!stat.isFile() || stat.size <= 0) return false;
        if (process.platform !== "win32") {
            if ((stat.mode & 0o022) !== 0) return false;
            fs.accessSync(candidate, fs.constants.X_OK);
        }
        return true;
    } catch { return false; }
}

export function findProtonConfgenExe(runtimeDirectory?: string): string {
    const found = candidatePaths().find(isUsableConfgenExecutable);
    if (found) return found;
    if (process.platform === "linux" && process.arch === "x64" && runtimeDirectory) {
        try { return materializeEmbeddedLinuxAsset("proton-confgen", runtimeDirectory); } catch {}
    }
    throw new Error("O executável proton-confgen não foi encontrado no pacote do plugin.");
}

function validProgress(value: unknown): ProtonOptimizationProgress | null {
    if (value === null || typeof value !== "object") return null;
    const raw = value as Record<string, unknown>;
    const phases: Record<string, true> = {
        ping: true,
        preparing: true,
        testing: true,
        finalizing: true,
        completed: true,
        failed: true,
        cancelled: true,
    };
    if (typeof raw.phase !== "string" || !phases[raw.phase]) return null;
    const totalValue = Number(raw.total);
    const testedValue = Number(raw.tested);
    const succeededValue = Number(raw.succeeded);
    const total = Number.isFinite(totalValue) ? Math.max(0, Math.floor(totalValue)) : 0;
    const tested = Number.isFinite(testedValue) ? Math.max(0, Math.min(total, Math.floor(testedValue))) : 0;
    const succeeded = Number.isFinite(succeededValue) ? Math.max(0, Math.min(tested, Math.floor(succeededValue))) : 0;
    const result: ProtonOptimizationProgress = { phase: raw.phase as ProtonOptimizationProgress["phase"], total, tested, succeeded };
    if (typeof raw.server === "string" && raw.server.length <= 200) result.server = raw.server;
    for (const key of ["downloadMbps", "uploadMbps", "pingMs"] as const) {
        const numeric = Number(raw[key]);
        if (Number.isFinite(numeric) && numeric > 0) result[key] = numeric;
    }
    if (raw.status === "testing" || raw.status === "success" || raw.status === "failed") result.status = raw.status;
    return result;
}

export function parseConfgenJson(stdout: string): Record<string, unknown> | undefined {
    for (const line of stdout.trim().split(/\r?\n/).reverse()) {
        const candidate = line.trim();
        if (!candidate.startsWith("{")) continue;
        try {
            const value = JSON.parse(candidate) as unknown;
            return value !== null && typeof value === "object" ? value as Record<string, unknown> : undefined;
        } catch {}
    }
    return undefined;
}

export function runConfgen(options: RunConfgenOptions): Promise<ConfgenResult> {
    return new Promise((resolve, reject) => {
        if (options.signal?.aborted) { reject(abortError()); return; }
        let executable: string;
        try {
            executable = path.resolve(options.exePath || findProtonConfgenExe(options.runtimeDirectory));
            if (!isUsableConfgenExecutable(executable)) throw new Error("O executável proton-confgen não foi encontrado ou é inválido.");
        }
        catch (error) { reject(error); return; }

        const timeoutMs = options.timeoutMs ?? 25_000;
        const child = spawn(executable, options.args, { windowsHide: true, env: { ...process.env } });
        let stdout = "";
        let stderr = "";
        let stderrBuffer = "";
        let settled = false;
        let aborted = false;
        let terminationError: Error | undefined;
        let killTimer: ReturnType<typeof setTimeout> | undefined;
        const stdoutDecoder = new StringDecoder("utf8");
        const stderrDecoder = new StringDecoder("utf8");

        const emitProgress = (chunk: string) => {
            stderrBuffer = (stderrBuffer + chunk).slice(-MAX_STDERR_BYTES);
            const lines = stderrBuffer.split(/\r?\n/);
            stderrBuffer = lines.pop() || "";
            for (const line of lines) {
                const match = /^\s*GOLIVE_PROGRESS\s+(\{.*\})\s*$/.exec(line);
                if (!match || terminationError) continue;
                try {
                    const progress = validProgress(JSON.parse(match[1]));
                    if (progress) options.onProgress?.(progress);
                } catch {}
            }
        };
        const finishReject = (error: Error) => {
            if (settled) return;
            settled = true;
            clearTimeout(timer);
            clearTimeout(killTimer);
            options.signal?.removeEventListener("abort", abort);
            reject(error);
        };
        const kill = (error: Error) => {
            if (settled || terminationError) return;
            terminationError = error;
            try { child.kill(); } catch {}
            killTimer = setTimeout(() => { if (!settled) { try { child.kill("SIGKILL"); } catch {} } }, 1000);
            killTimer.unref?.();
        };
        const timer = setTimeout(() => kill(new Error(`Tempo limite excedido (${Math.round(timeoutMs / 1000)}s) ao executar proton-confgen.`)), timeoutMs);
        timer.unref?.();
        const abort = () => { aborted = true; kill(abortError()); };
        options.signal?.addEventListener("abort", abort, { once: true });

        child.stdout.on("data", (chunk: Buffer) => { stdout = (stdout + stdoutDecoder.write(chunk)).slice(-MAX_STDOUT_BYTES); });
        child.stderr.on("data", (chunk: Buffer) => {
            const text = stderrDecoder.write(chunk);
            stderr = (stderr + text).slice(-MAX_STDERR_BYTES);
            emitProgress(text);
        });
        child.once("error", error => { terminationError ??= error; });
        child.stdin.on("error", error => {
            if ((error as NodeJS.ErrnoException).code !== "EPIPE") terminationError ??= error;
        });
        if (options.stdin !== undefined) child.stdin.end(options.stdin, "utf8");
        else child.stdin.end();
        // The signal can be aborted after the initial check but before the
        // listener is attached. Re-checking closes that small race window.
        if (options.signal?.aborted) abort();
        child.once("close", code => {
            if (settled) return;
            const stdoutTail = stdoutDecoder.end();
            const stderrTail = stderrDecoder.end();
            stdout = (stdout + stdoutTail).slice(-MAX_STDOUT_BYTES);
            stderr = (stderr + stderrTail).slice(-MAX_STDERR_BYTES);
            if (stderrTail) emitProgress(`${stderrTail}\n`);
            clearTimeout(timer);
            clearTimeout(killTimer);
            options.signal?.removeEventListener("abort", abort);
            if (terminationError || aborted) {
                finishReject(terminationError || abortError());
                return;
            }
            settled = true;
            resolve({ code, stdout, stderr, json: parseConfgenJson(stdout) });
        });
    });
}

export function classifyProtonError(error: unknown, stderr = "", stdout = ""): { code: ProtonLoginErrorCode; message: string; retryable: boolean } {
    const structured = classifyStructuredProtonCode(error);
    if (structured) return structured;
    const raw = `${error instanceof Error ? error.message : String(error)} ${stderr} ${stdout}`.toLowerCase();
    if (/captcha[_\s-]*(?:cancelled|canceled)|human verification.*cancel/.test(raw)) return { code: "CAPTCHA_CANCELLED", message: "A verificação Proton foi cancelada.", retryable: true };
    if (/captcha_invalid|captcha.*expired|human verification.*(invalid|expired)/.test(raw)) return { code: "CAPTCHA_INVALID", message: "A verificação de segurança expirou ou foi recusada.", retryable: true };
    if (/captcha_required|captcha verification required|human verification required|code 9001/.test(raw)) return { code: "CAPTCHA_REQUIRED", message: "O Proton solicitou uma verificação de segurança.", retryable: true };
    if (/\b9100\b/.test(raw)) return { code: "TWO_FACTOR_REQUIRED", message: "Esta conta exige autenticação em duas etapas.", retryable: false };
    const mentionsTwoFactor = /(?:\b2fa\b|two[\s_-]*factor|totp|verification code)/.test(raw);
    if (mentionsTwoFactor && /required|necessar|need(?:ed)?|exig/.test(raw)) return { code: "TWO_FACTOR_REQUIRED", message: "Esta conta exige autenticação em duas etapas.", retryable: false };
    if (mentionsTwoFactor) return { code: "TWO_FACTOR_INVALID", message: "O código 2FA está incorreto ou expirou.", retryable: false };
    if (/invalid credential|invalid password|wrong password|authentication failed|incorrect/.test(raw)) return { code: "INVALID_CREDENTIALS", message: "Usuário ou senha incorretos.", retryable: false };
    if (/secret[\s_-]*service|libsecret|safestorage|eacces|eperm|eexist|enotdir|not a directory|permission denied|access denied|read[- ]only|no space left|disk full|session.{0,80}(?:save|write|persistence|protect|decrypt|migrat|remove|delete)|(?:save|write|protect|decrypt|migrat|remove|delete).{0,80}session/.test(raw)) return { code: "SESSION_PERSISTENCE", message: "Não foi possível acessar o armazenamento local da sessão Proton.", retryable: true };
    if (/timeout|tempo limite|timed out/.test(raw)) return { code: "TIMEOUT", message: "O ProtonVPN demorou demais para responder.", retryable: true };
    if (/not found|enoent|spawn|não foi encontrado/.test(raw)) return { code: "MISSING_EXECUTABLE", message: "O componente ProtonVPN não foi encontrado nesta instalação.", retryable: false };
    if (/network|connection|dns|tls|temporar|unreachable|reset/.test(raw)) return { code: "NETWORK_ERROR", message: "Não foi possível conectar aos servidores ProtonVPN.", retryable: true };
    return { code: "UNKNOWN", message: "Não foi possível concluir a operação ProtonVPN.", retryable: true };
}

function classifyStructuredProtonCode(value: unknown): { code: ProtonLoginErrorCode; message: string; retryable: boolean } | null {
    if (typeof value !== "string") return null;
    switch (value.trim().toUpperCase()) {
        case "CAPTCHA_REQUIRED": return { code: "CAPTCHA_REQUIRED", message: "O Proton solicitou uma verificação de segurança.", retryable: true };
        case "CAPTCHA_INVALID": return { code: "CAPTCHA_INVALID", message: "A verificação de segurança expirou ou foi recusada.", retryable: true };
        case "CAPTCHA_CANCELLED": return { code: "CAPTCHA_CANCELLED", message: "A verificação Proton foi cancelada.", retryable: true };
        case "TWO_FACTOR_REQUIRED": return { code: "TWO_FACTOR_REQUIRED", message: "Esta conta exige autenticação em duas etapas.", retryable: false };
        case "TWO_FACTOR_INVALID": return { code: "TWO_FACTOR_INVALID", message: "O código 2FA está incorreto ou expirou.", retryable: false };
        case "INVALID_CREDENTIALS": return { code: "INVALID_CREDENTIALS", message: "Usuário ou senha incorretos.", retryable: false };
        case "NETWORK_ERROR": return { code: "NETWORK_ERROR", message: "Não foi possível conectar aos servidores ProtonVPN.", retryable: true };
        case "TIMEOUT": return { code: "TIMEOUT", message: "O ProtonVPN demorou demais para responder.", retryable: true };
        case "MISSING_EXECUTABLE": return { code: "MISSING_EXECUTABLE", message: "O componente ProtonVPN não foi encontrado nesta instalação.", retryable: false };
        case "SESSION_PERSISTENCE": return { code: "SESSION_PERSISTENCE", message: "Não foi possível acessar o armazenamento local da sessão Proton.", retryable: true };
        case "CONFIGURATION_ERROR": return { code: "CONFIGURATION_ERROR", message: "A configuração da conta Proton está incompleta.", retryable: false };
        case "UNKNOWN": return { code: "UNKNOWN", message: "Não foi possível concluir a operação ProtonVPN.", retryable: true };
        default: return null;
    }
}

export function protonSessionFile(dataDir: string): string {
    return path.join(path.resolve(dataDir), "proton-session.json");
}

function temporaryProtonSessionFile(dataDir: string): string {
    // O helper pode ser cancelado ou retornar um desafio CAPTCHA antes de
    // concluir. Uma sessão em staging impede que essas tentativas toquem na
    // sessão canônica que ainda pode ser válida.
    return path.join(path.resolve(dataDir), `.protonvpn-session-${randomUUID().replaceAll("-", "")}.tmp`);
}

const PROTON_ENVELOPE_FORMAT = "electron-safe-storage";
const PROTON_ENVELOPE_VERSION = 1;
const SAFE_STORAGE_UNAVAILABLE_MESSAGE =
    "O armazenamento seguro do sistema (Secret Service / libsecret) não está disponível para proteger a sessão Proton.";

interface ProtonSessionEnvelope {
    version: number;
    format: string;
    ciphertext: string;
}

interface SafeStorageLike {
    isEncryptionAvailable(): boolean;
    encryptString(plainText: string): Buffer;
    decryptString(encrypted: Buffer): string;
}

function getSafeStorage(): SafeStorageLike | null {
    try {
        const globalScope = globalThis as unknown as { __GOLIVE_SAFE_STORAGE__?: SafeStorageLike; electron?: { safeStorage?: SafeStorageLike } };
        const override = globalScope.__GOLIVE_SAFE_STORAGE__;
        if (override && typeof override.isEncryptionAvailable === "function") return override;
    } catch {}
    try {
        const globalScope = globalThis as unknown as { electron?: { safeStorage?: SafeStorageLike } };
        const { electron } = globalScope;
        if (electron?.safeStorage && typeof electron.safeStorage.isEncryptionAvailable === "function") {
            return electron.safeStorage;
        }
    } catch {}
    try {
        const req = typeof require === "function" ? require : undefined;
        const electron = req ? (req("electron") as { safeStorage?: SafeStorageLike } | undefined) : undefined;
        if (electron?.safeStorage && typeof electron.safeStorage.isEncryptionAvailable === "function") {
            return electron.safeStorage;
        }
    } catch {}
    return null;
}

function isSafeStorageAvailable(): boolean {
    const storage = getSafeStorage();
    if (!storage) return false;
    try {
        return storage.isEncryptionAvailable() === true;
    } catch {
        return false;
    }
}

function encryptProtonSession(plainText: string): string {
    const storage = getSafeStorage();
    if (!storage || !storage.isEncryptionAvailable()) {
        throw new Error(SAFE_STORAGE_UNAVAILABLE_MESSAGE);
    }
    const encrypted = storage.encryptString(plainText);
    const envelope: ProtonSessionEnvelope = {
        version: PROTON_ENVELOPE_VERSION,
        format: PROTON_ENVELOPE_FORMAT,
        ciphertext: encrypted.toString("base64"),
    };
    return JSON.stringify(envelope, null, 2);
}

function decryptProtonSession(envelopeRaw: string): string {
    const storage = getSafeStorage();
    if (!storage || !storage.isEncryptionAvailable()) {
        throw new Error(SAFE_STORAGE_UNAVAILABLE_MESSAGE);
    }
    let parsed: unknown;
    try {
        parsed = JSON.parse(envelopeRaw);
    } catch {
        throw new Error("A sessão Proton armazenada está corrompida ou ilegível.");
    }
    if (
        !parsed ||
        typeof parsed !== "object" ||
        (parsed as ProtonSessionEnvelope).version !== PROTON_ENVELOPE_VERSION ||
        (parsed as ProtonSessionEnvelope).format !== PROTON_ENVELOPE_FORMAT ||
        typeof (parsed as ProtonSessionEnvelope).ciphertext !== "string" ||
        !(parsed as ProtonSessionEnvelope).ciphertext.trim()
    ) {
        throw new Error("A sessão Proton armazenada não está no formato cifrado seguro.");
    }
    try {
        const buffer = Buffer.from((parsed as ProtonSessionEnvelope).ciphertext, "base64");
        return storage.decryptString(buffer);
    } catch {
        throw new Error("Não foi possível decifrar a sessão Proton com o armazenamento seguro do sistema.");
    }
}

// Sessão guardada apenas na memória deste processo.
//
// Algumas máquinas não têm armazenamento seguro utilizável: o Secret Service/
// libsecret não responde, o keyring está bloqueado ou o backend não é
// selecionado, e o Electron responde `isEncryptionAvailable() === false`. Antes
// disso o login era recusado por inteiro nessas máquinas -- o usuário não
// entrava nem com a senha correta. Agora a sessão autenticada vive só na
// memória deste processo: nada em texto claro fica no disco (o helper recebe
// uma cópia 0600 por operação, removida em `finally`) e a sessão deixa de valer
// quando o Discord reinicia, o que a UI avisa antes do login.
const inMemoryProtonSessions = new Map<string, string>();

export function protonSessionStorageMode(): ProtonSessionStorage {
    if (process.platform !== "linux") return "file";
    return isSafeStorageAvailable() ? "safe-storage" : "memory-only";
}

function rememberProtonSession(dataDir: string, plainText: string): void {
    inMemoryProtonSessions.set(dataDirKey(dataDir), plainText);
}

function forgetProtonSession(dataDir: string): void {
    inMemoryProtonSessions.delete(dataDirKey(dataDir));
}

function readRememberedProtonSession(dataDir: string): string | undefined {
    return inMemoryProtonSessions.get(dataDirKey(dataDir));
}

function isUsableSessionFile(file: string): boolean {
    try {
        const info = fs.lstatSync(file);
        return info.isFile() && !info.isSymbolicLink() && info.size > 0;
    } catch { return false; }
}

// Estado da sessão disponível para operar agora. `unreadable` é o arquivo
// cifrado que existe mas não pode ser aberto nesta execução (keyring ausente
// ou trocado) -- distinto de `none`, em que não há nada guardado.
type ProtonSessionAvailability = "memory" | "encrypted" | "plain" | "unreadable" | "none";

function protonSessionAvailability(dataDir: string): ProtonSessionAvailability {
    if (readRememberedProtonSession(dataDir) !== undefined) return "memory";
    const exists = isUsableSessionFile(protonSessionFile(dataDir));
    if (process.platform !== "linux") return exists ? "plain" : "none";
    if (!isSafeStorageAvailable()) return exists ? "unreadable" : "none";
    return exists ? "encrypted" : "none";
}

function writePrivateFileSync(target: string, content: string): void {
    let fd: number | undefined;
    try {
        fd = fs.openSync(target, "wx", 0o600);
        if (process.platform !== "win32") {
            try { fs.chmodSync(target, 0o600); } catch {}
        }
        fs.writeFileSync(fd, content, "utf8");
        try { fs.fsyncSync(fd); } catch {}
        fs.closeSync(fd);
        fd = undefined;
    } catch (error) {
        if (fd !== undefined) {
            try { fs.closeSync(fd); } catch {}
        }
        try { fs.rmSync(target, { force: true }); } catch {}
        throw error;
    }
}

function commitEncryptedSessionFromPlaintext(dataDir: string, plainTextStagingFile: string): boolean {
    let stagingEnvelope: string | undefined;
    try {
        if (!isUsableSessionFile(plainTextStagingFile)) return false;
        const plainText = fs.readFileSync(plainTextStagingFile, "utf8");
        const envelopeJson = encryptProtonSession(plainText);
        const target = protonSessionFile(dataDir);
        stagingEnvelope = temporaryProtonSessionFile(dataDir);
        writePrivateFileSync(stagingEnvelope, envelopeJson);
        fs.renameSync(stagingEnvelope, target);
        stagingEnvelope = undefined;
        if (process.platform !== "win32") {
            try { fs.chmodSync(target, 0o600); } catch {}
        }
        try { fs.rmSync(plainTextStagingFile, { force: true }); } catch {}
        return true;
    } catch {
        return false;
    } finally {
        if (stagingEnvelope !== undefined) {
            try { fs.rmSync(stagingEnvelope, { force: true }); } catch {}
        }
    }
}

// Materializa a sessão em memória numa cópia 0600 só para esta operação. Se o
// helper renovar o token, a memória é atualizada em vez do disco.
async function withMaterializedProtonSessionPlain<T>(
    dataDir: string,
    plainText: string,
    operation: (tempFile: string, commitIfUpdated: () => void) => Promise<T>,
): Promise<T> {
    const tempFile = temporaryProtonSessionFile(dataDir);
    writePrivateFileSync(tempFile, plainText);
    const commitIfUpdated = () => {
        try {
            if (!fs.existsSync(tempFile)) return;
            const updated = fs.readFileSync(tempFile, "utf8");
            if (updated && updated.trim() && updated !== plainText) rememberProtonSession(dataDir, updated);
        } catch {}
    };
    try {
        return await operation(tempFile, commitIfUpdated);
    } finally {
        try { fs.rmSync(tempFile, { force: true }); } catch {}
    }
}

function withMaterializedProtonSessionPlainSync<T>(
    dataDir: string,
    plainText: string,
    operation: (tempFile: string) => T,
): T {
    const tempFile = temporaryProtonSessionFile(dataDir);
    writePrivateFileSync(tempFile, plainText);
    try {
        return operation(tempFile);
    } finally {
        try { fs.rmSync(tempFile, { force: true }); } catch {}
    }
}

// Resolve a origem da sessão para a operação pedida. Todos os caminhos entregam
// ao helper apenas um arquivo regular 0600.
async function withProtonSession<T>(
    dataDir: string,
    availability: ProtonSessionAvailability,
    operation: (sessionFile: string, commitIfUpdated: () => void) => Promise<T>,
): Promise<T> {
    if (availability === "memory") return withMaterializedProtonSessionPlain(dataDir, readRememberedProtonSession(dataDir) ?? "", operation);
    if (availability === "encrypted") return withMaterializedProtonSession(dataDir, operation);
    if (availability === "plain") return operation(protonSessionFile(dataDir), () => {});
    throw new Error("Sessão Proton não encontrada.");
}

// Grava a sessão recém-autenticada. Sem armazenamento seguro no Linux nada em
// texto claro vai para o disco: a sessão fica na memória e o retorno é `false`
// para a UI avisar que ela vale só nesta execução. Falha de escrita também cai
// na memória -- o usuário não perde o login por causa do disco.
function persistProtonSession(dataDir: string, stagingFile: string, plainText: string): boolean {
    if (process.platform === "linux") {
        if (!isSafeStorageAvailable()) {
            rememberProtonSession(dataDir, plainText);
            return false;
        }
        if (commitEncryptedSessionFromPlaintext(dataDir, stagingFile)) return true;
        rememberProtonSession(dataDir, plainText);
        return false;
    }
    if (commitProtonSessionFile(stagingFile, protonSessionFile(dataDir))) return true;
    rememberProtonSession(dataDir, plainText);
    return false;
}

async function withMaterializedProtonSession<T>(
    dataDir: string,
    operation: (tempFile: string, commitIfUpdated: () => void) => Promise<T>,
): Promise<T> {
    const canonical = protonSessionFile(dataDir);
    if (!isUsableSessionFile(canonical)) {
        throw new Error("A sessão Proton armazenada não é um arquivo regular.");
    }
    const rawEnvelope = fs.readFileSync(canonical, "utf8");
    const plainText = decryptProtonSession(rawEnvelope);
    const tempFile = temporaryProtonSessionFile(dataDir);
    writePrivateFileSync(tempFile, plainText);

    const commitIfUpdated = () => {
        try {
            if (!fs.existsSync(tempFile)) return;
            const updated = fs.readFileSync(tempFile, "utf8");
            if (updated && updated.trim() && updated !== plainText) {
                commitEncryptedSessionFromPlaintext(dataDir, tempFile);
            }
        } catch {}
    };

    try {
        return await operation(tempFile, commitIfUpdated);
    } finally {
        try { fs.rmSync(tempFile, { force: true }); } catch {}
    }
}

function withMaterializedProtonSessionSync<T>(
    dataDir: string,
    operation: (tempFile: string) => T,
): T {
    const canonical = protonSessionFile(dataDir);
    if (!isUsableSessionFile(canonical)) {
        throw new Error("A sessão Proton armazenada não é um arquivo regular.");
    }
    const rawEnvelope = fs.readFileSync(canonical, "utf8");
    const plainText = decryptProtonSession(rawEnvelope);
    const tempFile = temporaryProtonSessionFile(dataDir);
    writePrivateFileSync(tempFile, plainText);
    try {
        return operation(tempFile);
    } finally {
        try { fs.rmSync(tempFile, { force: true }); } catch {}
    }
}

function commitProtonSessionFile(staging: string, target: string): boolean {
    try {
        const info = fs.lstatSync(staging);
        if (!info.isFile() || info.isSymbolicLink() || info.size <= 0) return false;
        // rename é a troca atômica no mesmo diretório; no Windows o runtime
        // usa MoveFileEx com substituição do arquivo de destino.
        fs.renameSync(staging, target);
        if (process.platform !== "win32") {
            try { fs.chmodSync(target, 0o600); } catch {}
        }
        return true;
    } catch {
        return false;
    }
}

function readSessionUsername(dataDir: string, sessionFile: string): string {
    const executable = path.resolve(findProtonConfgenExe(dataDir));
    const stdout = execFileSync(executable, ["-session-file", sessionFile, "-session-username", "-json"], {
        windowsHide: true,
        encoding: "utf8",
        stdio: ["ignore", "pipe", "ignore"],
        timeout: 5_000,
    });
    const value = parseConfgenJson(stdout);
    if (value?.success !== true || typeof value.username !== "string" || value.username.length > MAX_PROTON_USERNAME_LENGTH) return "";
    return normalizeProtonUsername(value.username);
}

export function savedSessionUsername(dataDir: string): string {
    try {
        const availability = protonSessionAvailability(dataDir);
        // Arquivo cifrado que não abre nesta execução não tem usuário a devolver:
        // o login será pedido de novo e substituirá a sessão.
        if (availability === "none" || availability === "unreadable") return "";
        if (availability === "memory")
            return withMaterializedProtonSessionPlainSync(dataDir, readRememberedProtonSession(dataDir) ?? "", tempFile => readSessionUsername(dataDir, tempFile));
        if (availability === "encrypted")
            return withMaterializedProtonSessionSync(dataDir, tempFile => readSessionUsername(dataDir, tempFile));
        return readSessionUsername(dataDir, protonSessionFile(dataDir));
    } catch { return ""; }
}

function cleanupSessionTempFiles(dataDir: string): boolean {
    const resolved = path.resolve(dataDir);
    let stat: fs.Stats;
    try { stat = fs.lstatSync(resolved); }
    catch (error) { return (error as NodeJS.ErrnoException).code === "ENOENT"; }
    if (stat.isSymbolicLink() || !stat.isDirectory()) return false;
    let ok = true;
    try {
        for (const entry of fs.readdirSync(resolved, { withFileTypes: true })) {
            if (!SESSION_TEMP_FILE_RE.test(entry.name)) continue;
            if (entry.isDirectory() && !entry.isSymbolicLink()) continue;
            try { fs.rmSync(path.join(resolved, entry.name), { force: true }); }
            catch { ok = false; }
        }
    } catch { return false; }
    return ok;
}

function deleteSessionArtifacts(dataDir: string): boolean {
    const resolved = path.resolve(dataDir);
    let stat: fs.Stats;
    try { stat = fs.lstatSync(resolved); }
    catch (error) { return (error as NodeJS.ErrnoException).code === "ENOENT"; }
    if (stat.isSymbolicLink() || !stat.isDirectory()) return false;
    try {
        fs.rmSync(protonSessionFile(resolved), { force: true });
        return cleanupSessionTempFiles(resolved);
    } catch { return false; }
}

function sessionCheckFailure(rawValue: unknown): { code: ProtonSessionCheckCode; error: string } {
    const raw = safeDiagnosticDetail(rawValue, 600).toLowerCase();
    if (/timeout|tempo limite|timed out/.test(raw)) return { code: "TIMEOUT", error: "A verificação da sessão Proton demorou demais." };
    if (/not found|enoent|spawn|não foi encontrado/.test(raw)) return { code: "MISSING_EXECUTABLE", error: "O componente ProtonVPN não foi encontrado nesta instalação." };
    if (/secret[\s_-]*service|libsecret|safestorage|eacces|eperm|eexist|enotdir|not a directory|permission denied|access denied|read[- ]only|no space left|disk full|session.{0,80}(?:save|write|persistence|protect|decrypt|migrat|remove|delete)|(?:save|write|protect|decrypt|migrat|remove|delete).{0,80}session/.test(raw)) return { code: "SESSION_PERSISTENCE", error: "Não foi possível acessar o armazenamento local da sessão Proton." };
    if (/network|connection|dns|tls|temporar|unreachable|reset|servidor|rede/.test(raw)) return { code: "NETWORK_ERROR", error: "Não foi possível verificar a sessão Proton por causa da rede." };
    if (/invalid|expired|session|token|unauthori[sz]ed|authentication/.test(raw)) return { code: "INVALID_SESSION", error: "A sessão Proton está inválida ou expirada." };
    return { code: "UNKNOWN", error: "Não foi possível verificar a sessão Proton." };
}

export function parseCaptchaUrl(rawUrl: string): { url: string; challenge: string; origin: string } | null {
    try {
        const parsed = new URL(rawUrl);
        const challenge = parsed.searchParams.get("Token")?.trim() || "";
        const host = parsed.hostname.toLowerCase();
        if (parsed.protocol !== "https:" || parsed.port !== "" || parsed.username || parsed.password || host !== "vpn-api.proton.me") return null;
        if (parsed.searchParams.getAll("Token").length !== 1) return null;
        if (parsed.pathname !== "/core/v4/captcha" || challenge.length < 3 || challenge.length > 4096) return null;
        if (/[\u0000-\u001f\u007f]/.test(challenge)) return null;
        const clean = new URL("/core/v4/captcha", parsed.origin);
        clean.searchParams.set("Token", challenge);
        return { url: clean.toString(), challenge, origin: clean.origin };
    } catch { return null; }
}

export function validateCaptchaResponse(value: unknown, challenge: string): value is string {
    if (typeof value !== "string") return false;
    const token = value.trim();
    if (token.length < 3 || token.length > 16_384 || !challenge || challenge.length > 4096 || /[\r\n]/.test(challenge) || token !== value) return false;
    return token.startsWith(`${challenge}:`) && token.length > challenge.length + 1 && !/[\r\n]/.test(token);
}

function ensureDataDir(dataDir: string): void {
    const resolved = path.resolve(dataDir);
    let ancestor = resolved;
    const { root } = path.parse(ancestor);
    while (ancestor !== root) {
        try {
            if (fs.lstatSync(ancestor).isSymbolicLink()) throw new Error("A pasta privada da sessão Proton não pode conter links simbólicos.");
        } catch (error) {
            if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
        }
        ancestor = path.dirname(ancestor);
    }
    try {
        const directoryInfo = fs.lstatSync(resolved);
        if (directoryInfo.isSymbolicLink() || !directoryInfo.isDirectory()) throw new Error("A pasta privada da sessão Proton não é um diretório regular.");
    } catch (error) {
        if ((error as NodeJS.ErrnoException).code !== "ENOENT") throw error;
        fs.mkdirSync(resolved, { recursive: true, mode: 0o700 });
    }
    const directoryInfo = fs.lstatSync(resolved);
    if (directoryInfo.isSymbolicLink() || !directoryInfo.isDirectory()) throw new Error("A pasta privada da sessão Proton não é um diretório regular.");
    if (process.platform !== "win32") fs.chmodSync(resolved, 0o700);
}

export async function checkProtonSession(dataDir: string, username: string): Promise<ProtonSessionCheckResult> {
    const requestedUsername = normalizeProtonUsername(username);
    if (!requestedUsername || requestedUsername.length > MAX_PROTON_USERNAME_LENGTH) return { valid: false, error: "Usuário Proton não especificado." };
    try {
        ensureDataDir(dataDir);
    } catch {
        return { valid: false, code: "SESSION_PERSISTENCE", error: "Não foi possível acessar o armazenamento local da sessão Proton." };
    }
    const availability = protonSessionAvailability(dataDir);
    if (availability === "none") {
        return { valid: false, code: "INVALID_SESSION", error: "Sessão Proton não encontrada." };
    }
    if (availability === "unreadable") {
        // O arquivo existe, mas o armazenamento seguro desta execução não abre o
        // envelope (keyring ausente ou trocado). Um login novo resolve.
        return { valid: false, code: "SESSION_PERSISTENCE", error: SAFE_STORAGE_UNAVAILABLE_MESSAGE };
    }
    try {
        return await withProtonSession(dataDir, availability, async (tempFile, commitIfUpdated) => {
            const result = await runConfgen({ args: ["-username", requestedUsername, "-session-file", tempFile, "-check-session", "-json"], runtimeDirectory: dataDir });
            if (result.code === 0 && result.json?.valid === true) {
                const returnedUsername = typeof result.json.username === "string" ? normalizeProtonUsername(result.json.username) : "";
                if (!returnedUsername || returnedUsername.length > MAX_PROTON_USERNAME_LENGTH || !usernamesMatch(requestedUsername, returnedUsername)) return { valid: false, code: "UNKNOWN", error: ACCOUNT_MISMATCH_ERROR };
                commitIfUpdated();
                return { valid: true, username: returnedUsername, expiresIn: typeof result.json.expiresIn === "string" ? result.json.expiresIn : undefined };
            }
            const failure = sessionCheckFailure(result.json?.error || result.stderr || "Sessão Proton inválida ou não encontrada.");
            return { valid: false, ...failure };
        });
    } catch (error) {
        return { valid: false, ...sessionCheckFailure(error) };
    }
}

export function normalizeProtonPlan(value: unknown): ProtonPlanResult {
    if (value === null || typeof value !== "object") return { success: false, status: "unknown", error: GENERIC_PLAN_ERROR };
    const raw = value as Record<string, unknown>;
    if (raw.success !== true || !Number.isInteger(raw.maxTier) || Number(raw.maxTier) < 0) return { success: false, status: "unknown", error: GENERIC_PLAN_ERROR };
    const result: ProtonPlanResult = { success: true, status: Number(raw.maxTier) === 0 ? "free" : "premium", maxTier: Number(raw.maxTier), checkedAt: new Date().toISOString() };
    for (const key of ["planName", "planTitle"] as const) if (typeof raw[key] === "string" && raw[key].trim()) result[key] = raw[key].trim().slice(0, 120);
    return result;
}

export async function getProtonPlan(dataDir: string, username: string, log?: RunConfgenOptions["log"]): Promise<ProtonPlanResult> {
    const requestedUsername = normalizeProtonUsername(username);
    if (!requestedUsername || requestedUsername.length > MAX_PROTON_USERNAME_LENGTH) return { success: false, status: "unknown", error: "Sessão Proton não encontrada." };
    try {
        ensureDataDir(dataDir);
    } catch {
        return { success: false, status: "unknown", error: "Não foi possível acessar o armazenamento local da sessão Proton." };
    }
    const availability = protonSessionAvailability(dataDir);
    if (availability === "none") {
        return { success: false, status: "unknown", error: "Sessão Proton não encontrada." };
    }
    if (availability === "unreadable") {
        return { success: false, status: "unknown", error: SAFE_STORAGE_UNAVAILABLE_MESSAGE };
    }
    try {
        return await withProtonSession(dataDir, availability, async (tempFile, commitIfUpdated) => {
            const result = await runConfgen({ args: ["-username", requestedUsername, "-session-file", tempFile, "-check-plan", "-json"], timeoutMs: 10_000, runtimeDirectory: dataDir, log });
            if (result.code === 0) {
                commitIfUpdated();
                return normalizeProtonPlan(result.json);
            }
            return { success: false, status: "unknown", error: GENERIC_PLAN_ERROR };
        });
    } catch (error) {
        log?.("warn", "falha ao consultar plano Proton", { erro: logError(error) });
        return { success: false, status: "unknown", error: GENERIC_PLAN_ERROR };
    }
}

export async function loginProton(
    dataDir: string,
    username: string,
    password?: string,
    twoFactorCode?: string,
    humanVerificationToken?: string,
    log?: RunConfgenOptions["log"],
): Promise<ProtonLoginResult> {
    const requestedUsername = normalizeProtonUsername(username);
    if (!requestedUsername || requestedUsername.length > MAX_PROTON_USERNAME_LENGTH) return { success: false, code: "CONFIGURATION_ERROR", message: "Informe o usuário Proton.", retryable: false };
    if (typeof password !== "string" || password.length === 0) return { success: false, code: "CONFIGURATION_ERROR", message: "Informe a senha Proton.", retryable: false };
    const key = dataDirKey(dataDir);
    const generation = protonLoginGenerations.get(key) ?? 0;
    return withProtonLoginLock(dataDir, async () => {
        if ((protonLoginGenerations.get(key) ?? 0) !== generation) return cancelledLoginResult();
        try {
            ensureDataDir(dataDir);
        } catch {
            return { success: false, code: "SESSION_PERSISTENCE", message: "Não foi possível acessar o armazenamento local da sessão Proton.", error: "Não foi possível acessar o armazenamento local da sessão Proton.", retryable: true };
        }
        const controller = new AbortController();
        activeProtonLogins.set(key, controller);
        const stagedSessionFile = temporaryProtonSessionFile(dataDir);
        const args = ["-username", requestedUsername, "-session-file", stagedSessionFile, "-login-only", "-json", "-stdin-secrets"];
        const stdin = `${JSON.stringify({
            password,
            twoFactorCode: twoFactorCode ?? "",
            humanVerificationToken: humanVerificationToken ?? "",
        })}\n`;
        try {
            const result = await runConfgen({ args, stdin, timeoutMs: 25_000, signal: controller.signal, runtimeDirectory: dataDir, log });
            if ((protonLoginGenerations.get(key) ?? 0) !== generation) {
                return cancelledLoginResult();
            }
            const structured = classifyStructuredProtonCode(result.json?.code);
            if (structured) {
                const captchaUrl = (structured.code === "CAPTCHA_REQUIRED" || structured.code === "CAPTCHA_INVALID") && typeof result.json?.captchaUrl === "string"
                    ? parseCaptchaUrl(result.json.captchaUrl)?.url
                    : undefined;
                return { success: false, ...structured, error: structured.message, captchaUrl };
            }
            if (result.code === 0 && result.json?.success === true) {
                const returnedUsername = typeof result.json.username === "string" ? normalizeProtonUsername(result.json.username) : "";
                if (!returnedUsername || returnedUsername.length > MAX_PROTON_USERNAME_LENGTH || !usernamesMatch(requestedUsername, returnedUsername)) return { success: false, code: "UNKNOWN", message: ACCOUNT_MISMATCH_ERROR, error: ACCOUNT_MISMATCH_ERROR, retryable: false };
                if (!isUsableSessionFile(stagedSessionFile)) {
                    return { success: false, code: "SESSION_PERSISTENCE", message: "A autenticação terminou, mas a sessão Proton não pôde ser preparada.", error: "A autenticação terminou, mas a sessão Proton não pôde ser preparada.", retryable: true };
                }
                const stagedPlainText = fs.readFileSync(stagedSessionFile, "utf8");
                const persisted = persistProtonSession(dataDir, stagedSessionFile, stagedPlainText);
                return {
                    success: true,
                    username: returnedUsername,
                    persisted,
                    message: persisted
                        ? "Autenticação Proton concluída."
                        : "Autenticação Proton concluída; esta máquina não guarda a sessão, então ela vale só nesta execução do Discord.",
                };
            }
            const detail = [result.json?.code, result.json?.error, result.stderr, result.stdout].filter(value => typeof value === "string" && value.length > 0).join(" ");
            const classified = classifyProtonError(detail);
            return { success: false, ...classified, error: classified.message };
        } catch (error) {
            if (controller.signal.aborted) {
                return cancelledLoginResult();
            }
            const classified = classifyProtonError(error);
            log?.("error", "falha ao executar login Proton", { codigo: classified.code, erro: logError(error) });
            return { success: false, ...classified, error: classified.message };
        } finally {
            if (activeProtonLogins.get(key) === controller) activeProtonLogins.delete(key);
            cleanupSessionTempFiles(dataDir);
        }
    });
}

function finitePositive(value: unknown): value is number {
    return typeof value === "number" && Number.isFinite(value) && value > 0;
}

export async function generateOptimalProtonConfig(
    dataDir: string,
    options: {
        username: string;
        country?: string;
        freeOnly?: boolean;
        autoPing?: boolean;
        speedTest?: boolean;
        signal?: AbortSignal;
        onProgress?: (progress: ProtonOptimizationProgress) => void;
        log?: RunConfgenOptions["log"];
    },
): Promise<ProtonOptimizationResult> {
    const requestedUsername = normalizeProtonUsername(options.username);
    if (!requestedUsername || requestedUsername.length > MAX_PROTON_USERNAME_LENGTH) return { success: false, error: "Sessão Proton não encontrada." };
    try {
        ensureDataDir(dataDir);
    } catch {
        return { success: false, error: "Não foi possível acessar o armazenamento local da sessão Proton." };
    }
    const availability = protonSessionAvailability(dataDir);
    if (availability === "none") {
        return { success: false, error: "Sessão Proton não encontrada." };
    }
    if (availability === "unreadable") {
        return { success: false, error: SAFE_STORAGE_UNAVAILABLE_MESSAGE };
    }

    const runGeneration = async (sessionFileToUse: string, commitIfUpdated?: () => void): Promise<ProtonOptimizationResult> => {
        const output = path.join(dataDir, "wireguard.conf");
        const staging = path.join(dataDir, `.wireguard.conf.${randomUUID()}.tmp`);
        const args = ["-username", requestedUsername, "-session-file", sessionFileToUse, "-output", staging, "-json", "-ipv6", "-exclude-countries", "BR"];
        if (options.autoPing !== false) args.push("-auto-ping");
        if (options.speedTest) {
            args.push("-speed-test", "-progress-json");
            if (process.platform === "win32") args.push("-require-discord");
        }
        if (options.freeOnly !== false) args.push("-free-only");
        if (options.country?.trim()) args.push("-countries", options.country.trim());

        try {
            const result = options.speedTest
                ? await runIsolatedSpeedSelection(args, options.signal, options.onProgress, options.log, dataDir)
                : await runConfgen({ args, timeoutMs: 60_000, signal: options.signal, runtimeDirectory: dataDir, onProgress: options.onProgress, log: options.log });
            const measured = !options.speedTest || (finitePositive(result.json?.downloadMbps) && finitePositive(result.json?.uploadMbps));
            if (result.code === 0 && result.json?.success === true && measured && fs.existsSync(staging)) {
                if (options.signal?.aborted) throw abortError();
                fs.renameSync(staging, output);
                if (process.platform !== "win32") {
                    try { fs.chmodSync(output, 0o600); } catch {}
                }
                commitIfUpdated?.();
                return {
                    success: true,
                    server: typeof result.json.server === "string" ? result.json.server : undefined,
                    country: typeof result.json.country === "string" ? result.json.country : undefined,
                    city: typeof result.json.city === "string" ? result.json.city : undefined,
                    tier: typeof result.json.tier === "string" ? result.json.tier : undefined,
                    load: finitePositive(result.json.load) ? result.json.load : undefined,
                    score: finitePositive(result.json.score) ? result.json.score : undefined,
                    pingMs: finitePositive(result.json.pingMs) ? result.json.pingMs : undefined,
                    downloadMbps: finitePositive(result.json.downloadMbps) ? result.json.downloadMbps : undefined,
                    uploadMbps: finitePositive(result.json.uploadMbps) ? result.json.uploadMbps : undefined,
                    speedTested: Number.isInteger(result.json.speedTested) ? Number(result.json.speedTested) : undefined,
                    speedSucceeded: Number.isInteger(result.json.speedSucceeded) ? Number(result.json.speedSucceeded) : undefined,
                    endpoint: typeof result.json.endpoint === "string" ? result.json.endpoint : undefined,
                    confFile: output,
                };
            }
            return { success: false, error: safeDiagnosticDetail(result.json?.error || result.stderr || "Falha ao gerar a configuração Proton.") };
        } catch (error) {
            if (error instanceof Error && error.name === "AbortError") throw error;
            options.log?.("error", "falha ao gerar configuração Proton", { erro: logError(error) });
            return { success: false, error: logError(error) };
        } finally {
            try { fs.rmSync(staging, { force: true }); } catch {}
            cleanupSessionTempFiles(dataDir);
        }
    };

    return withProtonSession(dataDir, availability, (tempFile, commitIfUpdated) => runGeneration(tempFile, commitIfUpdated));
}

export async function runIsolatedSpeedSelection(
    args: string[],
    signal?: AbortSignal,
    onProgress?: (progress: ProtonOptimizationProgress) => void,
    log?: RunConfgenOptions["log"],
    runtimeDirectory?: string,
): Promise<ConfgenResult> {
    if (process.platform === "win32") {
        return runConfgen({ args, timeoutMs: 210_000, runtimeDirectory, signal, onProgress, log });
    }
    const tempDir = await fs.promises.mkdtemp(path.join(os.tmpdir(), "golive-plugin-speed-"));
    const executable = path.join(tempDir, "golive-speed-probe");
    try {
        fs.copyFileSync(findProtonConfgenExe(runtimeDirectory), executable);
        fs.chmodSync(executable, 0o700);
        return await runConfgen({ args, exePath: executable, timeoutMs: 210_000, runtimeDirectory, signal, onProgress, log });
    } finally {
        await fs.promises.rm(tempDir, { recursive: true, force: true, maxRetries: 12, retryDelay: 200 }).catch(() => {});
    }
}

export function removeProtonSession(dataDir: string): boolean {
    cancelProtonLogin(dataDir);
    forgetProtonSession(dataDir);
    return deleteSessionArtifacts(dataDir);
}

export function cancelProtonLogin(dataDir: string): boolean {
    const key = dataDirKey(dataDir);
    protonLoginGenerations.set(key, (protonLoginGenerations.get(key) ?? 0) + 1);
    const active = activeProtonLogins.get(key);
    active?.abort();
    return Boolean(active);
}
